class Solution:
    def minimumTime(self, jobs: list[int], workers: list[int]) -> int:
        jobs.sort()
        workers.sort()
        return max((j + w - 1) // w for j, w in zip(jobs, workers))

class Solution {
public:
    int minimumTime(std::vector<int>& jobs, std::vector<int>& workers) {
        std::sort(jobs.begin(), jobs.end());
        std::sort(workers.begin(), workers.end());
        int ans = 0;
        for (size_t i = 0; i < jobs.size(); ++i) {
            ans = std::max(ans, (jobs[i] + workers[i] - 1) / workers[i]);
        }
        return ans;
    }
};

class Solution {
    public int minimumTime(int[] jobs, int[] workers) {
        java.util.Arrays.sort(jobs);
        java.util.Arrays.sort(workers);
        int ans = 0;
        for (int i = 0; i < jobs.length; ++i) {
            ans = Math.max(ans, (jobs[i] + workers[i] - 1) / workers[i]);
        }
        return ans;
    }
}

var minimumTime = function(jobs, workers) {
    jobs.sort((a, b) => a - b);
    workers.sort((a, b) => a - b);
    let ans = 0;
    for (let i = 0; i < jobs.length; ++i) {
        ans = Math.max(ans, Math.ceil(jobs[i] / workers[i]));
    }
    return ans;
};
